import json
import sqlite3


def _require_nonblank(value, name):
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{name} must be a nonblank string")
    return value


def _table_exists(connection, name):
    row = connection.execute(
        "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?",
        (name,),
    ).fetchone()
    return row is not None


def _decode_object(raw, label):
    try:
        value = json.loads(raw)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"invalid stored {label} JSON") from exc
    if not isinstance(value, dict):
        raise ValueError(f"stored {label} JSON must be an object")
    return value


def source_lookup(connection, project, source_id):
    """Return the source JSON dict if a confirmed review authorizes it."""
    _require_nonblank(project, "project")
    _require_nonblank(source_id, "source_id")

    if not _table_exists(connection, "nl_sources"):
        return None
    if not _table_exists(connection, "memory_review_candidates"):
        return None

    row = connection.execute(
        "SELECT source_json FROM nl_sources WHERE project_id = ? AND source_id = ?",
        (project, source_id),
    ).fetchone()
    if row is None:
        return None

    reviews = connection.execute(
        "SELECT candidate_json FROM memory_review_candidates "
        "WHERE project_id = ? AND status = ?",
        (project, "confirmed"),
    ).fetchall()

    authorized = False
    for (candidate_json,) in reviews:
        try:
            candidate = json.loads(candidate_json)
        except (TypeError, ValueError):
            continue
        if not isinstance(candidate, dict):
            continue
        draft = candidate.get("draft")
        if isinstance(draft, dict) and draft.get("source_id") == source_id:
            authorized = True
            break

    if not authorized:
        return None

    return _decode_object(row[0], "source")
