"""RepoMind maintenance helper. Contract is supplied in the task."""

import copy
import json
import math


def _encode(value):
    return json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")


def _has_nonfinite(value):
    if isinstance(value, float):
        return not math.isfinite(value)
    if isinstance(value, dict):
        return any(_has_nonfinite(k) or _has_nonfinite(v) for k, v in value.items())
    if isinstance(value, (list, tuple)):
        return any(_has_nonfinite(v) for v in value)
    return False


def _validate_fact(fact):
    if not isinstance(fact, dict):
        raise ValueError("each fact must be a dict")
    for field in ("source_id", "path"):
        value = fact.get(field)
        if not isinstance(value, str) or not value.strip():
            raise ValueError("fact %s must be a nonblank string" % field)
    if _has_nonfinite(fact):
        raise ValueError("fact contains nonfinite numbers")
    try:
        _encode(fact)
    except (TypeError, ValueError) as exc:
        raise ValueError("fact is not JSON serializable") from exc


def pack_facts(facts, max_bytes):
    if isinstance(max_bytes, bool) or not isinstance(max_bytes, int) or max_bytes < 2:
        raise ValueError("max_bytes must be a plain int >= 2")
    if not isinstance(facts, list):
        raise ValueError("facts must be a list")
    for fact in facts:
        _validate_fact(fact)

    packed = []
    for fact in facts:
        candidate = packed + [copy.deepcopy(fact)]
        if len(_encode(candidate)) <= max_bytes:
            packed = candidate
    return packed

