import json
import math


def _encode(value):
    return json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")


def _check_finite(value):
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("nonfinite number in facts")
    elif isinstance(value, dict):
        for key, item in value.items():
            if not isinstance(key, str):
                raise ValueError("non-string dict key in facts")
            _check_finite(item)
    elif isinstance(value, (list, tuple)):
        for item in value:
            _check_finite(item)


def _validate_fact(fact):
    if not isinstance(fact, dict):
        raise ValueError("each fact must be a dict")
    for field in ("source_id", "path"):
        value = fact.get(field)
        if not isinstance(value, str) or not value.strip():
            raise ValueError("fact %s must be a nonblank string" % field)
    _check_finite(fact)
    try:
        _encode(fact)
    except (TypeError, ValueError) as exc:
        raise ValueError("fact is not JSON serializable") from exc


def pack_facts(facts, max_bytes):
    if isinstance(max_bytes, bool) or not isinstance(max_bytes, int):
        raise ValueError("max_bytes must be a plain int")
    if max_bytes < 2:
        raise ValueError("max_bytes must be >= 2")
    if not isinstance(facts, list):
        raise ValueError("facts must be a list")

    for fact in facts:
        _validate_fact(fact)

    selected = []
    for fact in facts:
        candidate = selected + [fact]
        try:
            encoded = _encode(candidate)
        except (TypeError, ValueError) as exc:
            raise ValueError("fact is not JSON serializable") from exc
        if len(encoded) <= max_bytes:
            selected = candidate

    return json.loads(_encode(selected))
"}]}

