"""RepoMind maintenance helper. Contract is supplied in the task."""

from datetime import date, datetime, time, timezone
import copy

from repomind.domain.models import parse_timestamp


def _bound(value, *, is_end):
    """Normalize a bound to an aware UTC datetime.

    Dates map to UTC start-of-day (start) or end-of-day (end).
    """
    if isinstance(value, datetime):
        return parse_timestamp(value)
    if isinstance(value, date):
        if is_end:
            return datetime.combine(value, time.max, timezone.utc)
        return datetime.combine(value, time.min, timezone.utc)
    if isinstance(value, str):
        stripped = value.strip()
        if not stripped:
            raise ValueError("bound must not be blank")
        if len(stripped) == 10 and stripped[4] == "-" and stripped[7] == "-":
            try:
                parsed_date = date.fromisoformat(stripped)
            except ValueError as exc:
                raise ValueError("invalid date bound") from exc
            if is_end:
                return datetime.combine(parsed_date, time.max, timezone.utc)
            return datetime.combine(parsed_date, time.min, timezone.utc)
        return parse_timestamp(stripped)
    raise ValueError("bound must be an ISO timestamp, datetime, or date")


def _reviewed_at(value):
    """Parse a reviewed_at value; must be an aware timestamp, not a date."""
    if isinstance(value, datetime):
        return parse_timestamp(value)
    if isinstance(value, str):
        stripped = value.strip()
        if not stripped:
            raise ValueError("reviewed_at must not be blank")
        return parse_timestamp(stripped)
    raise ValueError("reviewed_at must be a timezone-aware timestamp")


def confirmed_window(records, project, start, end):
    if not isinstance(project, str) or not project.strip():
        raise ValueError("project must be a nonblank string")
    if not isinstance(records, list):
        raise ValueError("records must be a list")

    start_dt = _bound(start, is_end=False)
    end_dt = _bound(end, is_end=True)
    if start_dt > end_dt:
        raise ValueError("start bound must not be after end bound")

    result = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError("each record must be a dict")
        if record.get("project_id") != project:
            continue
        if record.get("status") != "confirmed":
            continue

        candidate_id = record.get("candidate_id")
        if not isinstance(candidate_id, str) or not candidate_id.strip():
            raise ValueError("confirmed record requires nonblank candidate_id")

        reviewed = _reviewed_at(record.get("reviewed_at"))
        if start_dt <= reviewed <= end_dt:
            result.append(copy.deepcopy(record))

    return result

