"""Select confirmed review records within an inclusive time window."""

from datetime import date, datetime, time, timezone
import copy

from repomind.domain.models import parse_timestamp


def _bound(value, *, is_end):
    """Normalize a window bound to an aware UTC datetime."""
    if isinstance(value, datetime):
        return parse_timestamp(value)
    if isinstance(value, date):
        moment = time.max if is_end else time.min
        return datetime.combine(value, moment, timezone.utc)
    if isinstance(value, str):
        try:
            return parse_timestamp(value, allow_date=True)
        except ValueError:
            raise
    raise ValueError("bound must be an ISO timestamp, datetime, or date")


def _is_blank(value):
    return not isinstance(value, str) or not value.strip()


def confirmed_window(records, project, start, end):
    """Return copies of confirmed records for project within [start, end]."""
    if _is_blank(project):
        raise ValueError("project must be a nonblank string")
    if not isinstance(records, list):
        raise ValueError("records must be a list")

    lower = _bound(start, is_end=False)
    upper = _bound(end, is_end=True)
    if lower > upper:
        raise ValueError("start must not be after end")

    selected = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError("each record must be a dict")
        if record.get("project_id") != project:
            continue
        if record.get("status") != "confirmed":
            continue
        candidate_id = record.get("candidate_id")
        if _is_blank(candidate_id):
            raise ValueError("confirmed record requires nonblank candidate_id")
        reviewed_at = record.get("reviewed_at")
        if isinstance(reviewed_at, date) and not isinstance(reviewed_at, datetime):
            raise ValueError("reviewed_at must be a timezone-aware timestamp, not a date")
        try:
            reviewed = parse_timestamp(reviewed_at)
        except ValueError as exc:
            raise ValueError("confirmed record requires timezone-aware reviewed_at") from exc
        if lower <= reviewed <= upper:
            selected.append(copy.deepcopy(record))
    return selected

